static inline bool dvm_platform_class_exists(const char *desc)
{
   size_t lo = 0, hi = sizeof dvm_platform_class_names / sizeof dvm_platform_class_names[0];
   while (lo < hi) {
      size_t mid = lo + (hi - lo) / 2;
      int cmp = strcmp(desc, dvm_platform_class_names[mid]);
      if (!cmp) return true;
      if (cmp < 0) hi = mid;
      else lo = mid + 1;
   }
   return false;
}
